const textSizeControls = () => {
  const storeKey = "prExplain.textScale";
  let percentage = TextScale.choose(BrowserStore.read(storeKey));
  const smaller = el("button", { type: "button", text: "A−", "aria-label": "文字を縮小", "data-text-scale": "decrease" });
  const larger = el("button", { type: "button", text: "A＋", "aria-label": "文字を拡大", "data-text-scale": "increase" });
  const reset = el("button", { type: "button", text: "100%に戻す", "aria-label": "文字サイズを100%に戻す", "data-text-scale": "reset" });
  const current = el("output", { class: "text-size-value", "aria-live": "polite", "aria-atomic": "true", "aria-label": "現在の文字サイズ", "data-text-scale": "value" });
  const render = () => {
    document.documentElement.style.setProperty("--text-scale", String(percentage / 100));
    current.textContent = `${percentage}%`;
    smaller.disabled = TextScale.decrease(percentage) === percentage;
    larger.disabled = TextScale.increase(percentage) === percentage;
    reset.disabled = percentage === TextScale.reset();
  };
  const update = (next) => {
    percentage = next;
    render();
    BrowserStore.write(storeKey, percentage);
  };
  smaller.addEventListener("click", () => update(TextScale.decrease(percentage)));
  larger.addEventListener("click", () => update(TextScale.increase(percentage)));
  reset.addEventListener("click", () => update(TextScale.reset()));
  render();
  return el("div", { class: "text-size-controls", role: "group", "aria-label": "文字サイズ" }, [
    el("span", { class: "text-size-label", text: "文字サイズ" }), smaller, current, larger, reset,
  ]);
};

const BrowserStore = Object.freeze({
  /** @returns 保存してある値。無い・読めないときは null */
  read: (key) => {
    try {
      const raw = localStorage.getItem(key);
      return raw === null ? null : JSON.parse(raw);
    } catch {
      return null;
    }
  },
  write: (key, value) => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // 残せないだけで、いま開いているページでは効いている。
    }
  },
});

/** 全 PR で共通の文字サイズ。保存できなくても、開いているページの操作は反映する。 */
const textSizeControls = () => {
  const storeKey = "prExplain.textScale";

const TextScale = (() => {
  const Default = 100;
  const Minimum = 80;
  const Maximum = 200;
  const Step = 10;
  const choose = (value) => {
    if (!Number.isInteger(value)) {
      return Default;
    }
    if (value < Minimum || value > Maximum) {
      return Default;
    }
    if (value % Step !== 0) {
      return Default;
    }
    return value;
  };
  return Object.freeze({
    choose,
    increase: (value) => Math.min(Maximum, choose(value) + Step),
    decrease: (value) => Math.max(Minimum, choose(value) - Step),
    reset: () => Default,
  });
})();

